#include <ctype.h>

#define MAX_LINE 100000
#define MAX_PANELS 1000
#define MAX_NAME 100

typedef struct {
    char name[MAX_NAME];
    int x1, y1, x2, y2;
    int parent; // index of parent panel, -1 for root
    int depth;  // number of directly above panels
} Panel;

Panel panels[MAX_PANELS];
int panel_count = 0;
int root_index = -1;

// Parse a panel definition like: panel_name(x1,y1,x2,y2)
void parse_panel(char *str) {
    char *token;
    char name[MAX_NAME];
    int x1, y1, x2, y2;

    // Extract name
    token = strtok(str, "(");
    if (token == NULL) return;
    strcpy(name, token);

    // Extract coordinates
    token = strtok(NULL, ")");
    if (token == NULL) return;

    if (sscanf(token, "%d,%d,%d,%d", &x1, &y1, &x2, &y2) != 4) return;

    // Store panel
    strcpy(panels[panel_count].name, name);
    panels[panel_count].x1 = x1;
    panels[panel_count].y1 = y1;
    panels[panel_count].x2 = x2;
    panels[panel_count].y2 = y2;
    panels[panel_count].parent = -1;
    panels[panel_count].depth = 0;
    panel_count++;
}

// Check if point (x,y) is inside panel p
int is_inside(int x, int y, int p) {
    return (x >= panels[p].x1 && x <= panels[p].x2 && 
            y >= panels[p].y1 && y <= panels[p].y2);
}

// Find the deepest panel containing point (x,y)
int find_panel(int x, int y) {
    int best = -1;
    int best_depth = -1;

    for (int i = 0; i < panel_count; i++) {
        if (is_inside(x, y, i)) {
            if (panels[i].depth > best_depth) {
                best_depth = panels[i].depth;
                best = i;
            }
        }
    }
    return best;
}

// Build parent relationships from nested structure
void build_hierarchy(char *input) {
    // Stack to track current parent at each nesting level
    int stack[MAX_PANELS];
    int stack_size = 0;
    int current_parent = -1;

    // Parse the input character by character
    char *p = input;
    char panel_def[MAX_LINE];
    int def_len = 0;
    int in_panel = 0;

    while (*p) {
        if (*p == '(' && *(p+1) != '(') {
            // Start of a panel definition
            in_panel = 1;
            def_len = 0;
            panel_def[def_len++] = *p;
        } else if (*p == ')' && in_panel) {
            panel_def[def_len++] = *p;
            panel_def[def_len] = '\0';

            // Parse the panel definition
            char temp[MAX_LINE];
            strcpy(temp, panel_def);
            parse_panel(temp);

            // Set parent relationship
            int new_panel = panel_count - 1;
            panels[new_panel].parent = current_parent;

            if (current_parent == -1) {
                panels[new_panel].depth = 0;
                root_index = new_panel;
            } else {
                panels[new_panel].depth = panels[current_parent].depth + 1;
            }

            // Push to stack
            stack[stack_size++] = new_panel;
            current_parent = new_panel;

            in_panel = 0;
        } else if (*p == ')' && !in_panel && stack_size > 0) {
            // Closing a nested structure
            stack_size--;
            if (stack_size > 0) {
                current_parent = stack[stack_size - 1];
            } else {
                current_parent = -1;
            }
        } else if (in_panel) {
            panel_def[def_len++] = *p;
        }
        p++;
    }
}

