void skip_spaces() {
    while (input[pos] && isspace(input[pos])) pos++;
}

void parse_panels(int parent_idx, int depth) {
    while (1) {
        skip_spaces();
        if (input[pos] == '<' && input[pos+1] == '/') break;
        if (input[pos] != '<') break;
        if (input[pos] == '\0') break;

        // Parse opening tag
        pos++; // skip '<'
        // Read tag content until '>'
        char tag[512];
        int ti = 0;
        while (input[pos] && input[pos] != '>') tag[ti++] = input[pos++];
        tag[ti] = '\0';
        pos++; // skip '>'

        // Parse name and attributes from tag
        char name[MAX_NAME] = "";
        int x=0,y=0,w=0,h=0;

        char *p = tag;
        // skip tag type (e.g., "Panel")
        while (*p && !isspace(*p)) p++;

        while (*p) {
            while (*p && isspace(*p)) p++;
            if (!*p) break;
            char attr[64]; int ai=0;
            while (*p && *p != '=') attr[ai++] = *p++;
            attr[ai] = '\0';
            p++; // skip '='
            if (*p == '"') p++;
            char val[256]; int vi=0;
            while (*p && *p != '"') val[vi++] = *p++;
            val[vi] = '\0';
            if (*p == '"') p++;

            if (strcmp(attr,"name")==0) strcpy(name,val);
            else if (strcmp(attr,"x")==0) x=atoi(val);
            else if (strcmp(attr,"y")==0) y=atoi(val);
            else if (strcmp(attr,"w")==0) w=atoi(val);
            else if (strcmp(attr,"h")==0) h=atoi(val);
        }

        int idx = panel_count++;
        strcpy(panels[idx].name, name);
        panels[idx].x = x; panels[idx].y = y;
        panels[idx].w = w; panels[idx].h = h;
        panels[idx].parent = parent_idx;
        panels[idx].depth = depth;

        parse_panels(idx, depth+1);

        // skip closing tag
        skip_spaces();
        if (input[pos] == '<') {
            while (input[pos] && input[pos] != '>') pos++;
            if (input[pos] == '>') pos++;
        }
    }
}

