#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXN 10005
#define MAXNAME 128
#define MAXSTR 1000005

typedef struct {
    char name[MAXNAME];
    int x1, y1, x2, y2;
    int parent;
    int firstChild;
    int nextSibling;
} Node;

static Node nodes[MAXN];
static int nodeCount = 0;

static char *s;
static int posi, len;

static void skip_spaces(void) {
    while (posi < len && isspace((unsigned char)s[posi])) posi++;
}

static int starts_with(const char *t) {
    int i = 0;
    while (t[i]) {
        if (posi + i >= len || s[posi + i] != t[i]) return 0;
        i++;
    }
    return 1;
}

static int read_int(void) {
    skip_spaces();
    int sign = 1, v = 0;
    if (s[posi] == '-') {
        sign = -1;
        posi++;
    }
    while (posi < len && isdigit((unsigned char)s[posi])) {
        v = v * 10 + (s[posi] - '0');
        posi++;
    }
    return sign * v;
}

static void read_word(char *out) {
    skip_spaces();
    int k = 0;
    while (posi < len && (isalnum((unsigned char)s[posi]) || s[posi] == '_' || s[posi] == '-')) {
        if (k < MAXNAME - 1) out[k++] = s[posi];
        posi++;
    }
    out[k] = '\0';
}

/*
   Expected tag format (generic XML-like):
   <name x1 y1 x2 y2> ... </name>
   Spaces/newlines may appear freely.
*/

static int parse_node(int parent) {
    skip_spaces();
    if (posi >= len || s[posi] != '<') return -1;
    posi++; // '<'

    if (posi < len && s[posi] == '/') return -1; // should not start with closing tag here

    char nm[MAXNAME];
    read_word(nm);
    int x1 = read_int();
    int y1 = read_int();
    int x2 = read_int();
    int y2 = read_int();

    skip_spaces();
    if (posi < len && s[posi] == '>') posi++;
    else return -1;

    int id = nodeCount++;
    strcpy(nodes[id].name, nm);
    nodes[id].x1 = x1;
    nodes[id].y1 = y1;
    nodes[id].x2 = x2;
    nodes[id].y2 = y2;
    nodes[id].parent = parent;
    nodes[id].firstChild = -1;
    nodes[id].nextSibling = -1;

    int lastChild = -1;

    while (1) {
        skip_spaces();
        if (posi >= len) break;

        if (starts_with("</")) {
            posi += 2;
            char closeName[MAXNAME];
            read_word(closeName);
            skip_spaces();
            if (posi < len && s[posi] == '>') posi++;
            break;
        } else if (s[posi] == '<') {
            int child = parse_node(id);
            if (child != -1) {
                if (nodes[id].firstChild == -1) nodes[id].firstChild = child;
                else nodes[lastChild].nextSibling = child;
                lastChild = child;
            } else {
                break;
            }
        } else {
            posi++;
        }
    }

    return id;
}

static int contains(int id, int x, int y) {
    return nodes[id].x1 <= x && x <= nodes[id].x2 &&
           nodes[id].y1 <= y && y <= nodes[id].y2;
}

static int find_deepest(int id, int x, int y) {
    if (!contains(id, x, y)) return -1;
    int c = nodes[id].firstChild;
    while (c != -1) {
        int r = find_deepest(c, x, y);
        if (r != -1) return r;
        c = nodes[c].nextSibling;
    }
    return id;
}

static int count_above(int id, int x, int y) {
    int p = nodes[id].parent;
    if (p == -1) return 0;
    int cnt = 0;
    int c = nodes[p].firstChild;
    int seen = 0;
    while (c != -1) {
        if (c == id) {
            seen = 1;
        } else if (!seen && contains(c, x, y)) {
            cnt++;
        }
        c = nodes[c].nextSibling;
    }
    return cnt;
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    getchar(); // consume trailing newline

    char *buffer = (char *)malloc(MAXSTR);
    if (!buffer) return 0;

    int idx = 0;
    int ch;
    while ((ch = getchar()) != EOF) {
        if (idx < MAXSTR - 1) buffer[idx++] = (char)ch;
    }
    buffer[idx] = '\0';

    /* Separate trailing 2*q integers from the tag text */
    int *nums = (int *)malloc(sizeof(int) * 2 * q);
    if (!nums) return 0;

    int found = 0;
    int i = idx - 1;
    while (i >= 0 && found < 2 * q) {
        while (i >= 0 && isspace((unsigned char)buffer[i])) i--;
        if (i < 0) break;

        int end = i;
        while (i >= 0 && (isdigit((unsigned char)buffer[i]) || buffer[i] == '-')) i--;
        int start = i + 1;

        char tmp[64];
        int L = end - start + 1;
        if (L <= 0 || L >= 64) break;
        memcpy(tmp, buffer + start, L);
        tmp[L] = '\0';
        nums[2 * q - 1 - found] = atoi(tmp);
        found++;
    }

    if (found != 2 * q) {
        free(nums);
        free(buffer);
        return 0;
    }

    buffer[i + 1] = '\0';

    s = buffer;
    len = (int)strlen(s);
    posi = 0;
    nodeCount = 0;

    int root = parse_node(-1);
    if (root == -1) {
        free(nums);
        free(buffer);
        return 0;
    }

    for (int k = 0; k < q; k++) {
        int x = nums[2 * k];
        int y = nums[2 * k + 1];

        if (!contains(root, x, y)) {
            printf("OUT OF MAIN PANEL\n");
            continue;
        }

        int sel = find_deepest(root, x, y);
        int above = count_above(sel, x, y);
        printf("%s %d\n", nodes[sel].name, above);
    }

    free(nums);
    free(buffer);
    return 0;
}

import sys
import re

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    q = int(data[0].strip())
    tag_str = data[1].strip()

    points = []
    for i in range(q):
        x, y = map(int, data[2 + i].split())
        points.append((x, y))

    # Parse tags of form:
    # <name x1 y1 x2 y2> ... </name>
    token_re = re.compile(r'<(/?)([A-Za-z0-9_]+)\s*([^>]*)>')

    stack = []
    nodes = []

    for m in token_re.finditer(tag_str):
        closing = m.group(1) == '/'
        name = m.group(2)
        rest = m.group(3).strip()

        if not closing:
            nums = list(map(int, rest.split()))
            x1, y1, x2, y2 = nums
            node = {
                'name': name,
                'x1': x1, 'y1': y1, 'x2': x2, 'y2': y2,
                'children': []
            }
            if stack:
                stack[-1]['children'].append(node)
            else:
                root = node
            stack.append(node)
            nodes.append(node)
        else:
            stack.pop()

    def inside(node, x, y):
        return node['x1'] <= x <= node['x2'] and node['y1'] <= y <= node['y2']

    # Find deepest panel containing point.
    # Among siblings, later declared child is on top.
    def find_selected(node, x, y):
        if not inside(node, x, y):
            return None
        for child in reversed(node['children']):
            res = find_selected(child, x, y)
            if res is not None:
                return res
        return node

    out = []
    for x, y in points:
        if not inside(root, x, y):
            out.append("OUT OF MAIN PANEL")
            continue

        selected = find_selected(root, x, y)

        # Count directly above panels:
        # siblings of selected with same parent, declared after selected,
        # that also contain the point.
        count_above = 0

        def count_in_parent(parent, target):
            nonlocal count_above
            ch = parent['children']
            idx = None
            for i, c in enumerate(ch):
                if c is target:
                    idx = i
                    break
            if idx is None:
                return
            for j in range(idx + 1, len(ch)):
                if inside(ch[j], x, y):
                    count_above += 1

        # Find parent of selected
        def dfs_parent(node, target):
            for c in node['children']:
                if c is target:
                    return node
                p = dfs_parent(c, target)
                if p is not None:
                    return p
            return None

        parent = dfs_parent(root, selected)
        if parent is not None:
            count_in_parent(parent, selected)

        out.append(f"{selected['name']} {count_above}")

    sys.stdout.write("\n".join(out))

