    public static void main2(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> allLines = new ArrayList<>();
        while (scanner.hasNextLine()) {
            allLines.add(scanner.nextLine());
        }

        if (allLines.isEmpty()) return;

        int T = Integer.parseInt(allLines.get(0).trim());

        // Find the tagged structure lines (lines 1 to where touch points start)
        // The touch points are the last T lines
        StringBuilder tagBuilder = new StringBuilder();
        int touchStart = allLines.size() - T;
        for (int i = 1; i < touchStart; i++) {
            tagBuilder.append(allLines.get(i)).append("\n");
        }
        String tagStructure = tagBuilder.toString().trim();

        // Parse structure
        Panel root = parseTagStructure(tagStructure);

        // Process touch points
        for (int i = touchStart; i < allLines.size(); i++) {
            String[] parts = allLines.get(i).trim().split("\\s+");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);

            processTouch(root, x, y);
        }

        scanner.close();
    }

    static void processTouch(Panel root, int x, int y) {
        if (!root.contains(x, y)) {
            System.out.println("out of the main panel");
            return;
        }

        // Find the deepest panel containing the point
        Panel selected = findDeepestPanel(root, x, y);
        int aboveCount = countAbovePanels(selected);

        System.out.println(selected.name + " " + aboveCount);
    }

    static Panel findDeepestPanel(Panel panel, int x, int y) {
        for (Panel child : panel.children) {
            if (child.contains(x, y)) {
                return findDeepestPanel(child, x, y);
            }
        }
        return panel;
    }

    static int countAbovePanels(Panel panel) {
        int count = 0;
        Panel current = panel.parent;
        while (current != null) {
            count++;
            current = current.parent;
        }
        return count;
    }

    static Panel parseTagStructure(String tagStructure) {
        // Remove outer brackets and split into tokens
        tagStructure = tagStructure.trim();
        if (tagStructure.startsWith("(") && tagStructure.endsWith(")")) {
            tagStructure = tagStructure.substring(1, tagStructure.length() - 1).trim();
        }

        return parsePanel(tagStructure);
    }

    static Panel parsePanel(String s) {
        // Format: name x y width height (children...)
        s = s.trim();

        // Find first space to get name
        int spaceIdx = s.indexOf(' ');
        String name = s.substring(0, spaceIdx);
        s = s.substring(spaceIdx + 1).trim();

        // Parse coordinates
        String[] parts = s.split("\\s+", 4);
        int x = Integer.parseInt(parts[0]);
        int y = Integer.parseInt(parts[1]);
        int width = Integer.parseInt(parts[2]);
        int height = Integer.parseInt(parts[3].split("\\(")[0].trim());

        Panel panel = new Panel(name, x, y, width, height);

        // Find children if any
        int openParen = s.indexOf('(');
        if (openParen != -1) {
            String childrenPart = s.substring(openParen);
            // Parse children
            List<String> childStrings = splitTopLevel(childrenPart);
            for (String childStr : childStrings) {
                Panel child = parsePanel(childStr);
                child.parent = panel;
                panel.children.add(child);
            }
        }

        return panel;
    }

    static List<String> splitTopLevel(String s) {
        List<String> result = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (depth == 0) {
                    start = i;
                }
                depth++;
            } else if (c == ')') {
                depth--;
                if (depth == 0) {
                    result.add(s.substring(start, i + 1));
                }
            }
        }
        return result;
    }

    // Corrected main method
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> allLines = new ArrayList<>();
        while (scanner.hasNextLine()) {
