        while (pos < input.length() && input.charAt(pos) != '>') pos++;
        String tagContent = input.substring(start, pos).trim();
        pos++; // skip '>'

        if (tagContent.startsWith("/")) return null; // closing tag

        // parse tag: panel name x y w h
        String[] parts = tagContent.split("\\s+");
        // parts[0] = "panel", parts[1]=name, parts[2]=x, parts[3]=y, parts[4]=w, parts[5]=h
        Panel p = new Panel();
        p.name = parts[1];
        p.x = Integer.parseInt(parts[2]);
        p.y = Integer.parseInt(parts[3]);
        p.w = Integer.parseInt(parts[4]);
        p.h = Integer.parseInt(parts[5]);

        // parse children
        while (true) {
            int savedPos = pos;
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
            if (pos < input.length() && input.charAt(pos) == '<') {
                int checkPos = pos + 1;
                while (checkPos < input.length() && input.charAt(checkPos) != '>') checkPos++;
                String nextTag = input.substring(pos+1, checkPos).trim();
                if (nextTag.startsWith("/")) {
                    pos = checkPos + 1; // consume closing tag
                    break;
                } else {
                    Panel child = parsePanel();
                    if (child != null) p.children.add(child);
                }
            } else {
                break;
            }
        }
        return p;
    }

    static String[] findPanel(Panel p, int px, int py, int depth) {
        if (!p.contains(px, py)) return null;
        // check children first (deepest match)
        for (Panel child : p.children) {
            String[] res = findPanel(child, px, py, depth + 1);
            if (res != null) return res;
        }
        return new String[]{p.name, String.valueOf(depth)};
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
