        int i = 0;
        StringBuilder panelSB = new StringBuilder();
        for (String l : lines) {
            String trimmed = l.trim();
            if (trimmed.matches("-?\\d+\\s+-?\\d+")) {
                String[] parts = trimmed.split("\\s+");
                touches.add(new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])});
            } else {
                panelSB.append(l).append("\n");
            }
        }
        input = panelSB.toString();
        pos = 0;
