import java.io.*;
import java.util.*;

/*
Assumption from the statement:
- Input:
    n
    <single line with tagged structure>
    x1 y1
    ...
    xn yn

Tagged structure format:
- A panel is represented as:
    <name x1 y1 x2 y2> ... </name>
- Panels may be nested.
- The first/opening tag contains the rectangle coordinates of that panel.
- Children inside a panel are "directly above" their parent, and among siblings,
  later declared panels are above earlier ones.
- For each touch point:
    * If outside the main/root panel => "OUT OF MAIN PANEL"
    * Else choose the topmost panel containing the point.
    * Output selected panel name and the number of panels directly above it.
      This count is the number of its direct children containing the point
      plus, for sibling overlap, the number of later siblings of that panel
      that also contain the point.

Since the original statement text is abbreviated, this parser is designed to
handle a common tagged-layout representation robustly.
*/

public class Main {
    static class Panel {
        String name;
        int x1, y1, x2, y2;
        Panel parent;
        List<Panel> children = new ArrayList<>();

        boolean contains(int x, int y) {
            int lx = Math.min(x1, x2), rx = Math.max(x1, x2);
            int ly = Math.min(y1, y2), ry = Math.max(y1, y2);
            return x >= lx && x <= rx && y >= ly && y <= ry;
        }
    }

    static class Tokenizer {
        List<String> tokens = new ArrayList<>();
        int idx = 0;

        Tokenizer(String s) {
            StringBuilder cur = new StringBuilder();
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c == '<' || c == '>' || Character.isWhitespace(c)) {
                    if (cur.length() > 0) {
                        tokens.add(cur.toString());
                        cur.setLength(0);
                    }
                    if (c == '<' || c == '>') tokens.add(String.valueOf(c));
                } else {
                    cur.append(c);
                }
            }
            if (cur.length() > 0) tokens.add(cur.toString());
        }

        boolean hasNext() { return idx < tokens.size(); }
        String next() { return tokens.get(idx++); }
        String peek() { return tokens.get(idx); }
    }

    static Panel parsePanel(Tokenizer tz, Panel parent) {
        // expects: < name x1 y1 x2 y2 >
        if (!tz.next().equals("<")) throw new RuntimeException("Expected <");
        String name = tz.next();
        int x1 = Integer.parseInt(tz.next());
        int y1 = Integer.parseInt(tz.next());
        int x2 = Integer.parseInt(tz.next());
        int y2 = Integer.parseInt(tz.next());
        if (!tz.next().equals(">")) throw new RuntimeException("Expected >");

        Panel p = new Panel();
        p.name = name;
        p.x1 = x1;
        p.y1 = y1;
        p.x2 = x2;
        p.y2 = y2;
        p.parent = parent;

        while (tz.hasNext()) {
            if (tz.peek().equals("<")) {
                if (tz.idx + 1 < tz.tokens.size() && tz.tokens.get(tz.idx + 1).startsWith("/")) {
                    tz.next(); // <
                    String closing = tz.next(); // /name
                    if (!tz.next().equals(">")) throw new RuntimeException("Expected >");
                    String closeName = closing.substring(1);
                    if (!closeName.equals(name)) throw new RuntimeException("Mismatched tag");
                    break;
                } else {
                    Panel child = parsePanel(tz, p);
                    p.children.add(child);
                }
            } else {
                tz.next(); // ignore stray token
            }
        }
        return p;
    }

    static Panel findTopmost(Panel p, int x, int y) {
        if (!p.contains(x, y)) return null;
        for (int i = p.children.size() - 1; i >= 0; i--) {
            Panel child = p.children.get(i);
            Panel got = findTopmost(child, x, y);
            if (got != null) return got;
        }
        return p;
    }

    static int countDirectlyAbove(Panel selected, int x, int y) {
        int count = 0;

        // direct children of selected that contain point are directly above it
        for (Panel ch : selected.children) {
            if (ch.contains(x, y)) count++;
        }

        // later siblings containing point are directly above selected
        if (selected.parent != null) {
            List<Panel> sib = selected.parent.children;
            int pos = -1;
            for (int i = 0; i < sib.size(); i++) {
                if (sib.get(i) == selected) {
                    pos = i;
                    break;
                }
            }
            for (int i = pos + 1; i < sib.size(); i++) {
                if (sib.get(i).contains(x, y)) count++;
            }
        }

        return count;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String first;
        do {
            first = br.readLine();
            if (first == null) return;
            first = first.trim();
        } while (first.isEmpty());

        int n = Integer.parseInt(first);

        String structure;
        do {
            structure = br.readLine();
            if (structure == null) return;
            structure = structure.trim();
        } while (structure.isEmpty());

        Tokenizer tz = new Tokenizer(structure);
        Panel root = parsePanel(tz, null);

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String line;
            do {
                line = br.readLine();
                if (line == null) line = "";
                line = line.trim();
            } while (line.isEmpty());

            StringTokenizer st = new StringTokenizer(line);
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());

            if (!root.contains(x, y)) {
                out.append("OUT OF MAIN PANEL\n");
            } else {
                Panel sel = findTopmost(root, x, y);
                int above = countDirectlyAbove(sel, x, y);
                out.append(sel.name).append(" ").append(above).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

