using namespace std;

struct Panel {
    string name;
    int x1, y1, x2, y2;
    vector<Panel> children;
    int depth;

    Panel() : x1(0), y1(0), x2(0), y2(0), depth(0) {}

    bool contains(int x, int y) const {
        return x >= x1 && x <= x2 && y >= y1 && y <= y2;
    }
};

struct TouchResult {
    string panelName;
    int aboveCount;
    bool valid;

    TouchResult() : panelName(""), aboveCount(0), valid(false) {}
};

Panel parsePanel(const string& input, int& pos, int depth) {
    Panel panel;
    panel.depth = depth;

    // Skip whitespace
    while (pos < input.length() && input[pos] == ' ') pos++;

    // Expect '('
    if (input[pos] != '(') {
        cerr << "Expected '(' at position " << pos << endl;
        return panel;
    }
    pos++;

    // Read tag name
    string tag;
    while (pos < input.length() && input[pos] != ' ' && input[pos] != '(' && input[pos] != ')') {
        tag += input[pos];
        pos++;
    }

    // Parse coordinates from tag
    // Format: panelName(x1,y1,x2,y2)
    size_t parenPos = tag.find('(');
    if (parenPos != string::npos) {
        panel.name = tag.substr(0, parenPos);
        string coords = tag.substr(parenPos + 1);
        coords = coords.substr(0, coords.length() - 1); // Remove trailing ')'

        stringstream ss(coords);
        string coord;
        vector<int> values;
        while (getline(ss, coord, ',')) {
            values.push_back(stoi(coord));
        }

        if (values.size() == 4) {
            panel.x1 = values[0];
            panel.y1 = values[1];
            panel.x2 = values[2];
            panel.y2 = values[3];
        }
    } else {
        // Simple tag without coordinates
        panel.name = tag;
    }

    // Parse children
    while (pos < input.length()) {
        // Skip whitespace
        while (pos < input.length() && input[pos] == ' ') pos++;

        if (pos >= input.length() || input[pos] == ')') {
            break;
        }

        if (input[pos] == '(') {
            Panel child = parsePanel(input, pos, depth + 1);
            panel.children.push_back(child);
        } else {
            break;
        }
    }

    // Expect ')'
    if (pos < input.length() && input[pos] == ')') {
        pos++;
    }

    return panel;
}

void findPanel(const Panel& panel, int x, int y, TouchResult& result, vector<string>& parentNames) {
    if (!panel.contains(x, y)) {
        return;
    }

    // This panel contains the point
    result.valid = true;
    result.panelName = panel.name;

    // Count directly above panels (siblings that overlap vertically with this panel)
    result.aboveCount = 0;

    // Check children first (we want the deepest panel)
    for (const Panel& child : panel.children) {
        TouchResult childResult;
        vector<string> childParents = parentNames;
        childParents.push_back(panel.name);
        findPanel(child, x, y, childResult, childParents);

        if (childResult.valid) {
            // Found a deeper panel
            result = childResult;
            return;
        }
    }

    // No deeper panel found, this is the selected panel
    // Count siblings that are directly above (same parent, higher y2)
    if (!parentNames.empty()) {
        // We need to find the parent panel to count siblings
        // This will be handled by the caller
    }
}

void countAbovePanels(const Panel& root, const string& targetName, int x, int y, int& count) {
    count = 0;

    // Find the target panel in the tree and count siblings above it
    function<bool(const Panel&, const string&)> findAndCount = 
        [&](const Panel& panel, const string& name) -> bool {
        if (panel.name == name && panel.contains(x, y)) {
            // Found the target panel, now count siblings above it
            // This requires access to the parent's children list
            return true;
        }

        for (const Panel& child : panel.children) {
            if (findAndCount(child, name)) {
                // Count siblings of this child that are above
                for (const Panel& sibling : panel.children) {
                    if (&sibling == &child) break;
                    // Check if sibling is directly above (overlaps in x-range and has higher y2)
                    if (sibling.x1 < child.x2 && sibling.x2 > child.x1 && 
                        sibling.y2 < child.y2) {
                        count++;
                    }
                }
                return true;
            }
        }
        return false;
    };

    findAndCount(root, targetName);
}

int main() {
    string line;

    // Read number of touch points
    getline(cin, line);
    int n = stoi(line);

    // Read the tag structure (may span multiple lines)
    string tagStructure;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        tagStructure += line;
        // Check if we have complete parentheses
        int openCount = 0;
        for (char c : tagStructure) {
            if (c == '(') openCount++;
            else if (c == ')') openCount--;
        }
        if (openCount == 0 && !tagStructure.empty()) {
            break;
        }
    }

    // Parse the tag structure
    int pos = 0;
    Panel root = parsePanel(tagStructure, pos, 0);

    // Process each touch point
    for (int i = 0; i < n; i++) {
        getline(cin, line);
        if (line.empty()) {
            i--;
            continue;
        }

        stringstream ss(line);
        int x, y;
        ss >> x >> y;

        // Find the panel containing this point
        TouchResult result;
        vector<string> parents;
        findPanel(root, x, y, result, parents);

        if (!result.valid) {
            cout << "OUT OF MAIN PANEL" << endl;
        } else {
            // Count directly above panels
            int aboveCount = 0;
            countAbovePanels(root, result.panelName, x, y, aboveCount);
            cout << result.panelName << " " << aboveCount << endl;
        }
    }

    return 0;
}

#include <bits/stdc++.h>
