struct Rect {
    string name;
    long long x1, y1, x2, y2;
    int depth;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    string s, line, tmp;
    cin >> ws;
    getline(cin, s);

    vector<pair<string, array<long long, 4>>> tags;

    // Parse all opening tags like:
    // <name x1 y1 x2 y2>
    for (size_t i = 0; i < s.size(); ) {
        if (s[i] == '<') {
            if (i + 1 < s.size() && s[i + 1] == '/') {
                size_t j = s.find('>', i);
                if (j == string::npos) break;
                i = j + 1;
            } else {
                size_t j = s.find('>', i);
                if (j == string::npos) break;
                string inside = s.substr(i + 1, j - i - 1);
                stringstream ss(inside);
                string name;
                long long x1, y1, x2, y2;
                ss >> name >> x1 >> y1 >> x2 >> y2;
                tags.push_back({name, {x1, y1, x2, y2}});
                i = j + 1;
            }
        } else {
            ++i;
        }
    }

    if (tags.empty()) {
        for (int i = 0; i < n; ++i) {
            long long x, y;
            cin >> x >> y;
            cout << "OUT OF MAIN PANEL\n";
        }
        return 0;
    }

    vector<Rect> rects;
    rects.reserve(tags.size());

    // Reconstruct nesting depths from the tagged string
    vector<Rect> stackRects;
    for (size_t i = 0; i < s.size(); ) {
        if (s[i] == '<') {
            if (i + 1 < s.size() && s[i + 1] == '/') {
                size_t j = s.find('>', i);
                if (j == string::npos) break;
                if (!stackRects.empty()) stackRects.pop_back();
                i = j + 1;
            } else {
                size_t j = s.find('>', i);
                if (j == string::npos) break;
                string inside = s.substr(i + 1, j - i - 1);
                stringstream ss(inside);
                Rect r;
                ss >> r.name >> r.x1 >> r.y1 >> r.x2 >> r.y2;
                r.depth = (int)stackRects.size();
                rects.push_back(r);
                stackRects.push_back(r);
                i = j + 1;
            }
        } else {
            ++i;
        }
    }

    auto contains = [&](const Rect& r, long long x, long long y) {
        return r.x1 <= x && x <= r.x2 && r.y1 <= y && y <= r.y2;
    };

    Rect mainPanel = rects[0];

    for (int qi = 0; qi < n; ++qi) {
        long long x, y;
        cin >> x >> y;

        if (!contains(mainPanel, x, y)) {
            cout << "OUT OF MAIN PANEL\n";
            continue;
        }

        int best = -1;
        int bestDepth = -1;
        for (int i = 0; i < (int)rects.size(); ++i) {
            if (contains(rects[i], x, y)) {
                if (rects[i].depth > bestDepth) {
                    bestDepth = rects[i].depth;
                    best = i;
                }
            }
        }

        cout << rects[best].name << " " << rects[best].depth << "\n";
    }

    return 0;
}
